@api_view(['POST'])
@permission_classes([permissions.IsAuthenticated])
def revoke_vault_access(request, vault_id):
    vault = get_object_or_404(KeyVault, id=vault_id)
    if not request.user.has_perm('admin_keyvault', vault):
        raise PermissionDenied("You do not have administrative permissions on this vault.")
    collaborator_id = request.data.get('collaborator_id')
    collaborator = get_object_or_404(User, id=collaborator_id)
    if ObjectPermissionChecker(collaborator).has_perm('access_keyvault', vault):
        remove_perm('access_keyvault', collaborator, vault)
        return Response({'status': 'access revoked'})
    return Response({'error': 'Collaborator does not hold permission'}, status=400)
